import{_ as t}from"./chunks/maintenance-pwr.pc.en.CVW_nHka.js";import{_ as o}from"./chunks/settings-cal.pc.en.X2_AiM35.js";import{_ as a,o as r,c as i,a5 as n}from"./chunks/framework.BYXPg_yw.js";const s="/RBQ/nightly/images/app/settings-chk.pc.en.png",d="/RBQ/nightly/images/app/maintenance-vision.pc.en.png",c="/RBQ/nightly/images/app/maintenance-ini.pc.en.png",y=JSON.parse('{"title":"Maintenance","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/maintenance.md","filePath":"manual/gui/maintenance.md","lastUpdated":1793350928000}'),h={name:"manual/gui/maintenance.md"};function l(p,e,b,u,m,f){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h1><p>Open <code>Maintenance</code> with its tile on the hub. The tile is shown to everyone and opens even without a robot connected; the sections that act on the robot need it connected. The sections sit as chips across the top:</p><ul><li><strong>Everyone:</strong> <code>Power / System</code>, <code>Calibration</code>, <code>Robot Check</code>, <code>PTZ Check</code> (robots with a PTZ only). Remote check is at the bottom of <code>Robot Check</code>.</li><li><strong><a href="/RBQ/nightly/manual/gui/developer-mode.html">Developer mode</a> only:</strong> <code>Vision</code>, <code>Config file</code>, and — on robots with an arm — <code>Arm</code>. Their chips carry an <code>Lv2</code> tag after the name.</li></ul><p>Software and firmware updates have their own screen — see <a href="/RBQ/nightly/manual/gui/software-update.html">Update</a>.</p><h2 id="power" tabindex="-1">Power / System <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power / System {#power}&quot;">​</a></h2><p><img src="'+t+'" alt="Power / System section"></p><p>While the in-app simulator is selected or another device is driving, the <code>Power / System</code> chip is dimmed and does not open. Like the Calibration tab, the screen is split into sections: <code>Top ports</code>, <code>Front / rear</code>, <code>Camera</code>, <code>Internal</code>, <code>Robot PC</code> and <code>Vision</code>. CAN-FD robots add <code>Bottom status LEDs (IF board)</code>, <code>Top LEDs (TOP board)</code> and <code>Inputs · Battery · Temperature</code> after <code>Internal</code>. Toggles and buttons show the real state from the robot and are disabled until that state has been received; a change can take about a second to show up.</p><p>In the power sections a toggle switches with one tap — except that turning off a <code>12V port</code> asks <code>Turn this off?</code> first, because the app cannot tell what is plugged in: it warns that the connected device loses power and that the app may lose its connection if a network device is plugged in. A row with a <code>Turn off</code> / <code>Turn on</code> button switches only after you confirm <code>Turn this off?</code> / <code>Turn this on?</code>. The confirmation is asked every time.</p><table tabindex="0"><thead><tr><th>Section</th><th>Non-CAN-FD robots</th><th>CAN-FD robots</th></tr></thead><tbody><tr><td><code>Top ports</code></td><td><code>12V port 1</code>–<code>4</code> (toggles, turning off asks first), <code>ARM · ADDON (48V)</code>, <code>EXTERN (48V)</code></td><td><code>12V port 1</code>–<code>4</code> (toggles, turning off asks first), <code>ARM · ADDON (48V)</code></td></tr><tr><td><code>Front / rear</code></td><td><code>Front / rear 12V</code> — front and rear switch together (toggle)</td><td><code>Front 12V</code>, <code>Rear 12V</code> (toggles)</td></tr><tr><td><code>Camera</code></td><td><code>Cameras (5V)</code> — all cameras, <code>Audio·USB hub (5V)</code></td><td>Cameras 0–5, <code>Side camera left (USB)</code>, <code>Side camera right (USB)</code> — one per camera, <code>Front hub reset</code>, <code>Rear hub reset</code></td></tr><tr><td><code>Internal</code></td><td><code>Speaker amp (12V)</code> (toggle), <code>User PC (12V)</code>, <code>LEGS (48V drive)</code></td><td><code>Speaker amp</code> (toggle), <code>LEGS (48V drive)</code>, <code>PDU (48V battery rail)</code> (display only)</td></tr></tbody></table><p><code>? Help</code> next to <code>Top ports</code> opens a dialog that will show where the top ports are; the picture will be added later. The 12V ports are named by number only, because what is plugged into them differs from robot to robot.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>ARM · ADDON (48V)</code> is one PDU port shared by the arm and the add-on. Turning it off also cuts arm power — make sure the arm is stopped first. Turning off the cameras or <code>User PC (12V)</code> stops video and audio.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Turning off <code>LEGS (48V drive)</code> drops the robot. It can be turned off only while the robot is not standing (sitting, control off or fallen); otherwise the row is blocked. Under <code>Robot PC</code>, <code>Restart robot service</code> — <code>Restart robot service</code> → <code>Restart the robot service?</code> → <code>Restart robot service</code> — restarts only the robot software and leaves the PC running; it works only from the device that holds control (otherwise <code>Restart request failed</code> — take control first, see <a href="/RBQ/nightly/manual/gui/control-home.html">Control home</a>). <code>Reboot robot PC</code> — <code>Reboot robot PC</code> → <code>Reboot the robot PC?</code> → <code>Reboot robot PC</code> — restarts the robot PC. A robot set up without that service shows <code>Restart request failed</code>; use <code>Reboot robot PC</code> then. Either way the robot loses motor power and the app connection drops. Sit the robot on the floor before either one.</p></div><p>On CAN-FD robots each row shows the live state, voltage and current, and the <code>Inputs · Battery · Temperature</code> section lists the charger inputs, both battery packs and the board temperatures.</p><p><code>Front hub reset</code> and <code>Rear hub reset</code> in the <code>Camera</code> section — <code>Reset</code> → <code>Reset the hub?</code> → <code>Reset</code> — make the side board restart its USB hub. Video from that board&#39;s three cameras (front <code>cameras 0 · 1 · 4</code>, rear <code>cameras 2 · 3 · 5</code>) drops briefly and comes back, and the result shows under the row. Only hw 1.1.0.1 side boards support this; older boards show <code>This side board does not support hub SMBus — only hw 1.1.0.1 boards do</code>.</p><p><code>VISION RESET</code> → <code>Reset</code> in the <code>Vision</code> section has the Handler restart the vision daemons, such as <code>HAL</code> and <code>Streamer</code>. HAL turns the cameras off and on again as it starts, so video stops until the cameras and the Streamer are back. The button shows <code>Resetting…</code> and stays unavailable for about 8 seconds.</p><h3 id="led-bottom" tabindex="-1">Bottom status LEDs <a class="header-anchor" href="#led-bottom" aria-label="Permalink to &quot;Bottom status LEDs {#led-bottom}&quot;">​</a></h3><p>On CAN-FD robots <code>Bottom status LEDs (IF board)</code> sits below the <code>Internal</code> section, one row for each of the two status LEDs under the body: <code>Right LED</code> and <code>Left LED</code>. A row shows the LED&#39;s current setting, its power in W, and a swatch of the color it actually puts out. <code>Settings</code> opens a dialog filled with what the robot reports. Under <code>Recommended</code>, pick <code>Keep off</code> or one of the values approved for RBQ; the dialog also shows the <code>Current setting</code>. Check <code>Apply the same to the other LED</code> to set both LEDs at once. <code>Apply</code> sends the setting and reads it back from the robot — <code>Applied — matches the robot</code> means the LED took it. <code>Reload</code> fills the dialog again from the robot.</p><p>The IF board limits LED power by itself (20 W instant, 10.5 W sustained), so a bright setting can come out dimmer than you set, and the row then shows <code>Limited</code>. When the robot cannot be read, the row shows <code>No reading</code> together with the last value this device read or sent. Right after the IF board restarts, the rows show <code>Not set — the IF board restarted and hasn&#39;t received a setting yet</code> until a setting reaches it. If the robot software is older than this feature, the rows read <code>The robot software doesn&#39;t have this feature yet. An update is needed</code>. If the IF board firmware is older than these LEDs need, the rows instead give the board&#39;s version and the minimum, for example <code>IF firmware update needed — it is 261003 and must be 261005 or later</code>, and <code>Apply</code> stays disabled until the board is updated.</p><p>Below them, <code>Top LEDs (TOP board)</code> has one row, <code>Lamp test</code>. Tapping <code>Lamp test</code> lights the seven LEDs on the top panel red, then green, then blue for 1.6 s, over whatever they were showing, and the seven dots next to the button follow the same colors so you can compare them with the real LEDs. The app only learns that the request was sent (<code>Sent — check that the 7 top LEDs change color along with the dots on the right</code>), so check the LEDs by eye. A TOP board with firmware older than 261006 runs the test only once it has been on for 10 s. If the robot software is older than this feature, the row reads <code>The robot software doesn&#39;t have this feature yet. An update is needed</code>.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#what-changes">Developer mode</a>.</p></blockquote><h2 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration {#calibration}&quot;">​</a></h2><p><img src="'+o+'" alt="Calibration section"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Every calibration here must be run with the robot on flat ground and <strong>stationary</strong>. The IMU and ZMP rows are blocked while the robot is walking, has fallen, or is not reporting its state, and each one asks <code>Run calibration?</code> before it sends the command. <code>Joint home-pose setup</code> has its own confirmation. Do not touch the robot until the calibration has finished.</p></div><h3 id="imu-calibration" tabindex="-1">IMU Calibration <a class="header-anchor" href="#imu-calibration" aria-label="Permalink to &quot;IMU Calibration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Accelerometer calib (ACC)</code></td><td>Field correction of accelerometer drift. Run it <strong>while the robot is sitting</strong>, on level ground; it averages the gravity magnitude for about 2 s and stores the factor.</td></tr><tr><td><code>IMU roll/pitch zero</code></td><td>Makes the current posture the level reference. Takes about half a second — if the robot is tilted when you run it, all later control will be off.</td></tr><tr><td><code>Gyro Bias Calibration</code></td><td>Resets the IMU, waits for the values to settle, then measures the gyro again — about 5 s, <strong>while the robot is sitting</strong>. When it finishes it reports all three axes and whether each one is within the limit. If the bias is still over the limit, hold the robot completely still and run it again.</td></tr></tbody></table><p>Press <code>Run</code>, then confirm <code>Run</code> in the dialog. When a row is blocked, the app tells you why, and if it can clear the block itself, a button appears next to <code>Run</code>: <code>Sit</code> when the robot needs to sit, <code>Stand</code> when it needs to stand, and <code>Auto Start</code> when control is off, which asks first. You get no such button while the robot has fallen, is docking, or is not reporting.</p><p><code>IMU roll/pitch zero</code> shows the current roll and pitch under the level in its dialog. A progress dialog follows while it runs. It ends with <code>Success</code> only when roll and pitch both come back within 1° — if the robot is still tilted, it reads <code>The zero may not have taken effect</code> instead, and you put the robot on flat ground and run it again.</p><h3 id="zmp-calibration" tabindex="-1">ZMP Calibration <a class="header-anchor" href="#zmp-calibration" aria-label="Permalink to &quot;ZMP Calibration&quot;">​</a></h3><p><code>Auto-calibrate ZMP offset</code> finds the center-of-mass offset automatically. The robot must be in STAND on flat ground. It walks one step to square up its legs, then takes up to 60 s to converge. Once the offset converges, the robot saves it on its own and returns to STAND. The panel shows the progress and a completion message.</p><h3 id="joint-calibration" tabindex="-1">Joint Calibration <a class="header-anchor" href="#joint-calibration" aria-label="Permalink to &quot;Joint Calibration&quot;">​</a></h3><p>Re-establishes the leg joints&#39; zeros and offsets. Run it with the robot <strong>sitting</strong>.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Joint home-pose setup</code></td><td>Hold the home pose with the jig, then store it as the joint zero — four legs</td></tr><tr><td><code>Motor Calibration</code></td><td>Re-establishes one joint&#39;s motor calibration reference in place — a popup with a button for every joint of the four legs</td></tr></tbody></table><p><code>Joint home-pose setup</code> opens two dialogs: first the notice (<em>This rewrites the joint zeros — running it without the jig, or with the pose off, leaves the robot booting on wrong zeros</em>), then the per-leg screen. On that screen, tap a joint card to see that joint move to its target pose in the 3D view on the left. Fit the jig, hold that pose, and press <code>Save LEG{n} {g} home pose</code> on that card — the roll card and the pitch/knee card each have their own button. Writing the zero switches control off (BOARD_RESET), so sit the robot down first — it will collapse if it is standing. The jig is required.</p><p>If the motor boards do not answer, the row is blocked with <em>No communication with the motor boards — turn the 48 V drive (LEGS) power on and run it again</em>; that rail is under <a href="#power">Power / System</a> on this page.</p><p>For the roll joint you pick the reference in the wizard: <code>Limit</code> pushes the joint against its inner limit as before, and <code>Level 0°</code> lets you make sure the body is level, set the joint to 0° with a bubble level, and shift the zero to match. Both references switch control off. The notice on closing offers <code>Auto Start</code> to bring the robot up again right away. If the correction is 9° or more, the robot rejects it and asks you to set the home against the limit first.</p><p><code>Motor Calibration</code> opens a popup with the robot seen from above and the four legs around it, each with a <code>Roll</code>, <code>Pitch</code> and <code>Knee</code> button. Press a button and that joint is calibrated right away, with no further confirmation: the board stops that joint for a moment, locks the rotor, stores the new reference and switches the joint back on, so its zero is kept and no restart is needed. The robot must be sitting (while it stands, a <code>Sit</code> button comes first). The button then reads <code>Done</code>, or <code>Rejected</code> / <code>No reply</code> when the board refused or the motor firmware does not support it. Do one joint at a time and do not touch the robot while it runs.</p><h3 id="camera-check" tabindex="-1">Camera Check · Calibration <a class="header-anchor" href="#camera-check" aria-label="Permalink to &quot;Camera Check · Calibration {#camera-check}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Basic Camera Check</code></td><td>Shows the live views of the six cameras with their FPS on one screen. Use the buttons at the top of each tile to choose the stream (RGB · IR · Depth). For cameras with an IR projector, whether it is on (<code>EMIT ON</code> · <code>EMIT OFF</code>) is shown to the left of those buttons. The <code>IR projector (all)</code> toggle at the top of the window turns the IR projectors of all cameras on or off together. It is for checking by eye that no view is blocked or blurry; it gives no verdict.</td></tr><tr><td><code>Lower Depth Camera On-chip Calibration</code></td><td>Runs on-chip calibration for the lower depth cameras. See <a href="#on-chip">On-chip calibration</a> below.</td></tr><tr><td><code>Lower Depth Camera Position Calibration</code></td><td>Calibrates the positions of the four lower depth cameras with the calibration board plate. See <a href="#position-calibration">Position calibration</a> below.</td></tr></tbody></table><h3 id="docking-calibration" tabindex="-1">Docking calibration <a class="header-anchor" href="#docking-calibration" aria-label="Permalink to &quot;Docking calibration&quot;">​</a></h3><p>The bottom of the Calibration section holds the auto-docking alignment parameters: <code>Offset X (m)</code>, <code>Offset Y (m)</code>, <code>Req Count</code>, <code>Try Count</code>.</p><ul><li><code>Reload</code> re-reads the values from the robot.</li><li><code>Defaults</code> fills the fields with factory defaults — nothing is saved until you press <code>Apply</code>.</li><li><code>Apply</code> writes the values to the robot and reads them back.</li></ul><h2 id="robot-check" tabindex="-1">Robot Check <a class="header-anchor" href="#robot-check" aria-label="Permalink to &quot;Robot Check {#robot-check}&quot;">​</a></h2><p><img src="'+s+'" alt="Robot Check section"></p><p><code>Robot Check</code> checks the robot&#39;s condition in order, from sitting to walking. Each stage is a card: press <code>Measure</code>, read the result, and if a value is out of range, fix it on the spot with the button next to it. The fix buttons work whether or not you have measured — they only follow the robot&#39;s state. An out-of-range value only marks the card <code>Caution</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Stages 2, 4 and 5 move the robot by itself, and joystick input is ignored while they run. Clear 1 m around the robot before you start. <code>Stop</code> ends the run and the robot stands.</p></div><h3 id="gait-check" tabindex="-1">Gait Check <a class="header-anchor" href="#gait-check" aria-label="Permalink to &quot;Gait Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stage</th><th>Robot</th><th>What it measures</th><th>Reference</th><th>Fix</th></tr></thead><tbody><tr><td>1 <code>Sitting · IMU</code></td><td>Sitting</td><td>Gravity magnitude and gyro bias, averaged over 3 s</td><td>9.75 ~ 9.85 m/s², gyro under 1.0 °/s</td><td><code>Accelerometer Calibration</code>, <code>Gyro Bias Calibration</code></td></tr><tr><td>2 <code>Motor Calibration Status</code></td><td>Standing</td><td>Lifts one leg at a time, relaxes the knee, pitch and roll in turn and locks the rotor on the three phases (U·V·W) to measure how far it is from the stored motor calibration reference, in electrical degrees — the worst of the three is dropped and the other two are judged</td><td>±6° (electrical): both within = normal, one outside = caution, both outside = fail</td><td><code>Calibrate again</code> (asked in a popup at a failed joint)</td></tr><tr><td>3 <code>Standing · Level</code></td><td>Standing</td><td>Roll and pitch over 2 s, after you level the body by hand with a bubble level placed on it</td><td>±0.3°</td><td><code>IMU roll/pitch zero</code></td></tr><tr><td>4 <code>Joint Communication</code></td><td>Standing</td><td>CAN communication of each joint while the body twists left and right up to 30°, five times (about 10 s) — <code>Per motor</code>: missed frames, lowest receive rate, longest receive gap; <code>Per channel</code>: <code>Error frames</code>, <code>error-warning</code>, <code>error-passive</code>, <code>bus-off</code></td><td>450 Hz or more received, gaps of 10 ms or less</td><td>—</td></tr><tr><td>5 <code>Trot in place · Drift</code></td><td>Standing</td><td>Trots in place for 10 s, stands again, and compares the body position with the start</td><td>under ±10 cm fore-aft, under ±5 cm lateral</td><td><code>Visual Check</code>, then <code>Joint home-pose setup</code>, then <code>ZMP Calibration</code></td></tr></tbody></table><ul><li>Stage 2: this card&#39;s button is <code>Start calibration</code>. Press it and the robot stands on three legs and lifts each leg in turn to measure (about 20 s per leg), then returns to standing on four legs by itself. Do not touch the robot while it measures. If a joint is judged as fail, the robot holds that pose and asks whether to <code>Calibrate again</code>. If you do not choose within 30 s, it skips calibration and moves on to the next joint. The popup shows the two values used for the verdict. After calibrating it measures that joint again. If every value is now within the limit, the popup title says the motor DQ check passed and <code>Next joint</code> is the main button, with <code>Calibrate again</code> beside it; otherwise it asks again whether to <code>Calibrate again</code> or move on to the <code>Next joint</code>. The table fills in as each joint finishes while the robot is still measuring.</li><li>Stage 4: if a joint is out of range, the card names the leg and asks you to check the wiring between the body and that leg module. Compare the missed frames between joints: a joint that misses frames while the others do not points to that leg&#39;s wiring. <code>Per channel</code> lists the CAN channels the legs are on, with the legs on each. <code>Error frames</code> counts how many times the channel reported a state change (error-warning, error-passive, bus-off or recovery) during the twist. These numbers are shown for reference and are not part of the verdict. The sim has no CAN measurement, so it is not judged there.</li><li>Stage 5: if the robot drifts 10 cm or more fore-aft or 5 cm or more sideways, the card marks every direction that drifted and recommends <code>Visual Check</code>, then <code>Joint home-pose setup</code>, then <code>ZMP Calibration</code>, in that order. The home-pose setup is the same wizard as in Calibration and needs the robot sitting — while it stands, a <code>Sit</code> button comes first.</li></ul><h3 id="camera-check-1" tabindex="-1">Camera Check <a class="header-anchor" href="#camera-check-1" aria-label="Permalink to &quot;Camera Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stage</th><th>What it measures</th><th>Verdict</th><th>Fix</th></tr></thead><tbody><tr><td>1 <code>Camera View · FPS</code></td><td>Status and RGB · IR · Depth FPS of the six cameras, for 10 s</td><td><code>Needs service</code> if a stream falls below 70% of its target FPS three times, or twice in a row</td><td><code>Basic Camera Check</code></td></tr><tr><td>2 <code>Depth Camera Quality</code></td><td>Depth quality of the floor in the middle of the view, for each lower depth camera (about 2 s each)</td><td><code>Normal</code>, <code>OCC advised</code>, <code>Check view</code>, <code>No plane</code>, <code>No stream</code></td><td><code>On-Chip Calibration</code></td></tr><tr><td>3 <code>Depth Camera Alignment</code></td><td>Roll · pitch · z of each lower depth camera against the reference plane, and on the calibration board also x · y · yaw against the neighbouring camera (about 4 s)</td><td><code>Normal</code>, <code>Needs calibration</code>, <code>No plane</code>, <code>Board not in view</code>, <code>Off</code></td><td><code>Lower Depth Camera Position Calibration</code></td></tr></tbody></table><p>The fix buttons open the same dialogs as <a href="#camera-check">Calibration › Camera Check · Calibration</a>.</p><ul><li>Stage 1: the table shows each camera&#39;s status, USB link speed and FPS per stream. A camera on USB2 gets a note to check the cable and port, separate from the verdict. Connections can change quickly, so the result is cleared when you leave <code>Robot Check</code>.</li><li>Stage 2: measure with the robot standing on a flat floor. The cameras need the standing height above the floor, so while the robot sits, <code>Measure</code> and <code>On-Chip Calibration</code> are blocked and a stand button comes first. The robot keeps the last result, so it is still shown when you come back, until you measure again. Hover over or tap the <code>?</code> next to a metric name for its description. <ul><li><code>FILL</code> — the share of pixels in the middle of the view that have a depth value. When it is low you get <code>Check view</code>: make sure the lens is not blocked and the robot is not sitting.</li><li><code>SUBPIXEL</code> — how far the points deviate from the floor plane, in disparity (px); this is the stereo matching precision. Above the threshold you get <code>OCC advised</code>.</li><li><code>PLANE RMS</code> — the same deviation in mm. It grows with distance, so it is for reference.</li><li><code>No plane</code> means no floor plane was found in the middle of the view.</li><li><code>Quality</code> is the measured depth quality; <code>Calibration</code> is the result of the last on-chip calibration (<code>Saved</code>, <code>Kept original</code>, <code>Failed</code>). A failed calibration does not change <code>Quality</code>.</li></ul></li><li>Stage 3: measure with the robot standing on a flat floor. As in stage 2, while the robot sits, <code>Measure</code> is blocked and a stand button comes first, and the robot keeps the last result. The result comes in two tables. <ul><li><code>① Against the reference plane — roll · pitch · z</code> — compares Bottom0 · 1 · 3 with the plane the reference sensor Bottom2 sees. If Bottom2 finds no plane, the reason appears in red under the table.</li><li><code>② Against the neighbouring camera — x · y · yaw</code> — the position and heading difference between two neighbouring cameras (<code>Bottom1 ↔ Bottom2</code>, <code>Bottom3 ↔ Bottom2</code>, <code>Bottom0 ↔ Bottom1</code>) that see the same board. It appears only when you measure on the calibration board; the floor alone cannot show x · y · yaw.</li><li>The <code>Reference</code> row shows the threshold for each axis, and values above it are shown in orange. If any axis is above its threshold, that camera shows <code>Needs calibration</code>.</li></ul></li></ul><h4 id="on-chip" tabindex="-1">On-chip calibration <a class="header-anchor" href="#on-chip" aria-label="Permalink to &quot;On-chip calibration {#on-chip}&quot;">​</a></h4><p>The camera recomputes the stereo calibration of a lower depth camera by itself. Keep the robot standing on a flat floor and do not move it until it finishes.</p><ol><li>Choose the cameras to calibrate. Each camera shows the verdict of the last measurement, and the <code>OCC advised</code> ones are already selected. If nothing has been measured, all four are selected.</li><li>Press <code>Start calibration</code>. Each camera goes through measuring, computing OCC, then applying and re-measuring.</li><li>The result table shows <code>SUBPIXEL</code> and <code>PLANE RMS</code> before → after, with the change in percent. If the result is clearly better, the robot saves the new calibration to the camera and you see <code>Saved</code>; otherwise it restores the original values right away and you see <code>Kept original</code>.</li><li>To calibrate again, press <code>Re-calibration</code>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A saved calibration stays in the camera and is kept after the robot restarts. Do not move the robot until the calibration finishes.</p></div><p>If OCC fails on a camera, check that it can see the floor (lens blocked, robot sitting) and run it again. After you close the dialog, the table on the <code>Depth Camera Quality</code> card shows the values after calibration.</p><h4 id="position-calibration" tabindex="-1">Position calibration <a class="header-anchor" href="#position-calibration" aria-label="Permalink to &quot;Position calibration {#position-calibration}&quot;">​</a></h4><p>This calibrates the positions of the four lower depth cameras with the calibration board plate. The top of the dialog shows four steps: <code>Pre-check</code> · <code>Measure</code> · <code>Calibrating</code> · <code>Results</code>.</p><p>The plate carries five calibration boards (boards 1–5) in one row with no gaps. Board 1 goes at the robot&#39;s front, and each board&#39;s printed top edge faces the front of the robot. Stand the robot on a flat floor first, then slide the plate under the body, between the four legs, with the top edge of the boards toward the front of the robot.</p><ol><li><code>Pre-check</code> — press <code>Start measure</code> and the robot looks at the board in the middle of the plate and walks to the middle of the plate. Progress shows <code>Finding the board</code> → <code>Walking</code> → <code>Done</code>, and the robot walks up to twice until it is in place. If the plate is placed the other way round, the robot does not walk and you see <code>The calibration board is upside down. Place it again with its top edge toward the front of the robot.</code> Turn the plate around and start again. Press <code>Stop</code> to stop walking and stand. Once the robot is in place, the measurement starts on its own.</li><li><code>Measure</code> — the four camera tiles and the two tables above appear. If a camera does not see enough of the board, move the robot to the middle of the plate and press <code>Measure Again</code>. If all four are normal, no calibration is needed. If any shows <code>Needs calibration</code>, press <code>Start Calibration</code>.</li><li><code>Calibrating</code> — the neighbouring cameras are aligned to the reference sensor Bottom2 in turn. This calibration does not change Bottom2.</li><li><code>Results</code> — the robot measures again after calibrating. If all four are normal, it keeps the calibration and you see <code>Calibrated</code>; otherwise it reverts all four to the values before calibrating and you see <code>Reverted without calibrating</code>. If there was nothing to change, you see <code>Already normal</code>. After keeping a calibration you can still go back to the previous values with <code>Revert to Before</code>. If it was reverted, check that the plate has not shifted and press <code>Calibrate Again</code>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>During <code>Pre-check</code> the robot walks on its own. Clear the area around the robot before you start. After that, do not move the robot or the plate until it finishes.</p></div><p><code>Revert to Before</code> works only until vision is restarted.</p><h3 id="remote-check" tabindex="-1">Remote check <a class="header-anchor" href="#remote-check" aria-label="Permalink to &quot;Remote check {#remote-check}&quot;">​</a></h3><p><code>Remote check</code> is the last section at the bottom of <code>Robot Check</code>. Turning it on lets Rainbow Robotics support check this robot from outside your network for a limited time. Support joins the robot through the app to see its state and operate it, and over SSH to work on the robot PC with the same rights as a technician on site — reading logs, changing settings and software, restarting the robot software or rebooting it, and sending robot commands. The robot makes a one-time key itself and gives it to support only, so you never set or pass on a password. The robot must be connected to the internet — see <a href="/RBQ/nightly/manual/operation/robot-internet.html">Connecting the Robot to the Internet</a>. Remote check is turned on in the robot, so the app must be connected to it; otherwise this section only shows <code>Not connected to a robot</code>.</p><ol><li>When support asks you to turn on remote check, press <code>Turn on 1h</code>, <code>Turn on 2h</code> or <code>Turn on 4h</code> in this section. Support never connects or asks to connect on their own — it starts only when you turn it on.</li><li>If it cannot turn on, the reason appears in red under the buttons. <code>Could not turn on — The robot is not connected to the internet</code> means the robot must reach the internet first — see <a href="/RBQ/nightly/manual/operation/robot-internet.html">Connecting the Robot to the Internet</a>. <code>Could not turn on — The robot&#39;s SSH server is not running</code> means the robot PC is not ready to accept the connection — turn the robot off and on again, and contact support if it keeps happening.</li><li>While it is on, a <code>Remote check on</code> banner on every screen of a device connected directly to the robot (not over a remote connection) shows the number of SSH connections, the time left and a <code>Disconnect</code> button. Connecting does not take control away from you. If support takes control to operate the robot, this device becomes a spectator and shows <code>Rainbow Robotics support is controlling remotely · tap to take control</code> — tap it to take control back at any time. <code>E-STOP</code>, the banner&#39;s <code>Disconnect</code> and this section keep working while you spectate — Maintenance then shows only <code>Robot Check</code>, with only this section in it.</li><li><code>Disconnect</code> ends support&#39;s app and SSH connections at once, along with anything support left running on the robot PC. Running out of time does the same. Turn it on again for the next check.</li></ol><p>Every turn-on, disconnect and connection is written to the robot&#39;s system log, with the address it came from. If the robot is not registered for remote connection yet, pressing a <code>Turn on</code> button first asks to register it with the Rainbow server (<code>Remote registration</code>). Press <code>Register</code> — registration alone lets no one in — and then <code>Restart robot service</code>, which restarts the robot software and leaves the PC running, or <code>Reboot robot PC</code> (both stay greyed out while the robot is standing — sit it first; if <code>Restart robot service</code> fails, use <code>Reboot robot PC</code>); once the robot is back, turn remote check on again. The phone needs internet for this, which it gets through the robot once the robot is connected to the internet (see <a href="/RBQ/nightly/manual/operation/robot-internet.html">Connecting the Robot to the Internet</a>). Press <code>Cancel</code> to leave the robot unregistered. If only part of the settings is missing, the section lists what is missing (for example <code>Remote connection is turned off (enabled)</code> or <code>The robot name is empty (robot_id)</code>), and <code>Turn on</code> asks to fill in only those values (<code>Fill in</code>) before the restart. If the robot is already registered with the server but its key is gone, the section says so — ask support to register it again.</p><p>You can turn it on and off without the app: open <code>http://&lt;robot address&gt;:8080</code> in a browser on the robot&#39;s network, sign in, and press <code>Turn on · 1 h</code> (2 h, 4 h) in <code>Settings</code> › <code>Remote check</code>. <code>Disconnect</code> ends it. The same page lists missing remote connection settings and registers an unregistered robot the same way as the app (<code>Restart robot</code> afterwards); the device opening the page needs the internet for this.</p><h2 id="ptz-check" tabindex="-1">PTZ Check <a class="header-anchor" href="#ptz-check" aria-label="Permalink to &quot;PTZ Check {#ptz-check}&quot;">​</a></h2><p>Shown only on robots with a PTZ (the unit that pans and tilts the cameras). The robot checks the PTZ axes, cameras, sound and communication in turn and keeps the results. The check runs on the robot, so it finishes even if you close the app, and any device can watch it or stop it. The section has two tabs, <code>Tests</code> and <code>Results</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>During the check the PTZ axes move from end to end and the camera speaker beeps at 1 kHz and 2 kHz for 2 s each. Keep the area around the axes clear. In a noisy place step 13 (speaker → microphone) can FAIL. The PTZ cannot be controlled while the check runs, and if someone controlled the PTZ within the last 10 s the start dialog warns you.</p></div><h3 id="kinds-of-check" tabindex="-1">Kinds of check <a class="header-anchor" href="#kinds-of-check" aria-label="Permalink to &quot;Kinds of check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>User</th><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td>Everyone</td><td><code>Start check</code></td><td>16 steps, about 2 min. The stored current zeros are only read and range-checked, and the preset steps 11 and 18 are left out</td></tr><tr><td><a href="/RBQ/nightly/manual/gui/developer-mode.html">Developer mode</a></td><td><code>Start basic check</code></td><td>Steps 1–18. Measures and saves the current zeros again. The preset steps (11, 18) run if you agree at the start</td></tr><tr><td><a href="/RBQ/nightly/manual/gui/developer-mode.html">Developer mode</a></td><td><code>Start aging check</code></td><td>Steps 1–18 → soak (<code>30 min</code>, <code>2 h</code>, <code>12 h</code>, 12 h by default) → recheck (20), then the final report. PITCH current is limited to 3 A during the soak and released afterwards</td></tr></tbody></table><p>Step 3 (<code>Firmware up to date</code>) is skipped for now and shows <code>Skipped — no reference firmware on the robot</code>: the reference firmware does not ship with the robot software yet.</p><p>In an aging check, if steps 1–18 have a FAIL you are asked <code>End here</code> or <code>Continue aging</code> before the soak. With no answer for 10 minutes it ends. If you continue, the final report stays FAIL.</p><p>While the check runs, the <code>Tests</code> tab shows the step table and the current PTZ angles; during the soak it shows the current chart and the status so far (position signals, command vs position, communication round trip, camera video). <code>Stop</code> ends the check and keeps the result as <code>Invalid</code>. A robot battery at 10 % or below, or a power cut during the check, also leaves it <code>Invalid</code>.</p><h3 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h3><p>The <code>Results</code> tab lists up to the 20 latest PTZ checks on this robot; the oldest is removed when a new one is added. Tap a row to open its report — verdict, results table, key values, what/how/why and the criteria for each step, the soak charts and the recheck comparison. Recordings (30 s) can only be viewed on the same network as the robot.</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PASS</code></td><td>Normal</td></tr><tr><td><code>WARN</code></td><td>Needs a check — usable; review it with support at the next service</td></tr><tr><td><code>FAIL</code></td><td>Contact support</td></tr><tr><td><code>Invalid</code></td><td>The check did not finish (stopped, battery, power cut). It is not a product verdict — run the check again</td></tr></tbody></table><p>The latest check has <code>Re-run steps</code>: only the steps you pick from 1–18 run again, together with the preparation steps they need (1, 2, 17 and so on). The first results are kept, and a step that first FAILed only raises the overall verdict to <code>WARN</code> even if a re-run passes. When a finished result has not been viewed yet, the hub <code>Maintenance</code> tile shows a dot.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision {#vision}&quot;">​</a></h2><p><img src="'+d+'" alt="Vision section"></p><p>Vision toggles — night mode, stealth, IR projector, video resolution and the rest — are in the <code>Vision</code> popover on the control screen; see <a href="/RBQ/nightly/manual/gui/camera-vision.html">Camera &amp; Vision</a>. This section holds the developer tools.</p><p><code>Camera Calibration</code>:</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Jig Extrinsic Calibration</code></td><td>Calibrates each sensor&#39;s base↔sensor transform from the jig markers. The robot must be seated on the calibration jig. The result is written to the HAL settings.</td></tr><tr><td><code>OAK-D Intrinsic Calibration</code></td><td>Calibrates the front and rear stereo cameras while walking. The front camera must face a ChArUco board within 1 m. The result is written to each camera&#39;s EEPROM.</td></tr></tbody></table><p><code>Run</code> opens a confirmation that lists what to check first; progress and the result appear in the top banner. While a calibration runs, both buttons change to <code>Cancel</code>.</p><p>The <code>OAK-D Intrinsic Calibration</code> window follows the step bar at the top (<code>Pre-check</code> → <code>Board approach</code> → <code>Capture</code> → <code>Compute · write</code> → <code>Results</code>). In <code>Pre-check</code>, pick the <code>Walk mode</code>: <code>RL Walk</code>, <code>Wave</code> or <code>Stairs</code>, and press <code>Start</code>. Each time the window opens, it starts at <code>RL Walk</code> on a legged robot and <code>Stairs</code> on a wheeled robot. The window stays open after the start; in <code>Capture</code> it shows where the robot is for the front camera and the rear camera, from the board approach to the 180° turn. <code>Results</code> shows success or failure for the front and the rear OAK-D. The robot keeps going if you close the window; only then does the top banner appear, and pressing it opens the window again. Press <code>Stop</code> to stop partway.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The OAK-D intrinsic calibration makes the robot walk around by itself for about 10 minutes. Keep 1.5 m around the robot clear before starting it.</p></div><p><code>Daemon control</code> — <code>VISION RESET</code> → <code>Reset</code> has the Handler restart every vision daemon the robot keeps running, such as <code>HAL</code> and <code>Streamer</code> — all but <code>Vision</code>, which runs the Handler. HAL turns the cameras off and on again as it starts, so video stops until the cameras and the Streamer are back. The button shows <code>Resetting…</code> and stays unavailable for about 8 seconds.</p><p><code>Vision Programs</code> lets you start and stop individual vision daemons by hand (<code>Vision</code>, <code>HAL</code>, <code>Streamer</code>, <code>Handeye</code>, <code>Heightmap</code>, <code>Ptz</code>). Their on/off state comes from the robot&#39;s reported program status; only on older daemons that do not report it does it fall back to the last command sent. <code>Stop</code> does not leave a daemon off: with the default settings the robot starts each of them again within a few seconds. Use this to apply a changed setting without a reboot: for example, press <code>Streamer</code> once after changing an RTSP setting in <code>Streamer.ini</code>. While the Streamer restarts, the app&#39;s video drops for a few seconds. Stopping <code>HAL</code> turns the cameras off and on again, as <code>VISION RESET</code> does, so video stays off until the cameras are back.</p><h2 id="config-file" tabindex="-1">Config file <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;Config file {#config-file}&quot;">​</a></h2><p><img src="'+c+'" alt="Config file section"></p><p>The INI editor edits the robot daemons&#39; configuration files directly. The toggles at the top turn <code>Motion.ini</code>, <code>HAL · config.ini</code>, <code>Handler · config.ini</code> and <code>Streamer.ini</code> on and off; with several on, they are listed one after another. <code>Search keys, values, sections</code> searches every file that is on and opens only the sections with a match. Sections start folded: tap one to open it, or use <code>Expand all</code> and <code>Collapse all</code>. <code>Changed only</code> shows just the keys you have edited. The search row stays at the top while you scroll. Boolean values can be toggled, other values are edited in place. Each file&#39;s header shows how many sections were read and when.</p><p>In <code>Motion.ini</code>, the robot&#39;s model values (gear ratios, link masses, limits) come from a platform profile built into the robot software, and the editor shows those keys dimmed. Editing one and saving stores it in <code>Motion.ini</code> as an override for this robot, and the key is then highlighted. The <code>Reset to profile</code> button next to an override puts the profile value back; saving a value equal to the profile removes the key from the file.</p><p>The footer counts unsaved edits (<code>{n} changes</code>). <code>Revert</code> discards them, <code>Reload</code> re-reads the open files from the robot, <code>Save</code> opens the confirmation <code>Save to {label}?</code> (or <code>Save to {n} config files?</code> when several files changed), listing every changed key with its old and new value.</p><p>The robot reads these files only when the program that uses them starts, so <code>Save and restart</code> saves the files and then restarts that program:</p><ul><li><code>Motion.ini</code> and <code>Handler · config.ini</code>: the robot software restarts while the computer stays on. The app loses the robot for a moment.</li><li><code>HAL · config.ini</code> and <code>Streamer.ini</code>: only HAL or the Streamer restarts. Video stops until it is back.</li><li>A change only in the <code>[BlackBox]</code> section of <code>Streamer.ini</code> applies right away, so nothing restarts.</li></ul><p>Saving works only while the robot is sitting or its control is off; otherwise the confirmation shows <code>Sit the robot or turn control off before saving (now {gait})</code>. Restarting the robot software also needs this device to be in control.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Saving replaces the <strong>entire</strong> file on the robot with what the editor holds — always edit on top of a freshly loaded file. On a robot with a separate vision PC, the app cannot restart Vision: after saving <code>Handler · config.ini</code>, the app says so, and the change applies once the vision PC restarts. Do not change values whose meaning you do not know.</p></div><h2 id="arm" tabindex="-1">Arm <a class="header-anchor" href="#arm" aria-label="Permalink to &quot;Arm&quot;">​</a></h2><p>Shown only when the robot reports an arm. This section is the initial bring-up.</p><ol><li>Press <code>CAN check</code>, <code>Release brake</code>, <code>Control Start</code> in that order. Wait for the status badge to light up after each step before pressing the next. ▶ Auto Start ARM runs the whole sequence in one press.</li><li><code>Static poses</code> sends a fixed pose (<code>Straight</code>, <code>Folding</code>, <code>Ready</code>, <code>Lift</code>, <code>Packing</code>, <code>DoorReady</code>) without a trajectory — on the first use start from <code>Ready</code>.</li><li><code>Joint lock / jog</code> — tap a joint card to lock or unlock it; hold <code>+</code> / <code>−</code> to jog a locked joint (the buttons are disabled while the joint is unlocked).</li></ol>',102)])])}const v=a(h,[["render",l]]);export{y as __pageData,v as default};
